    #[test]
    fn transient_auth_prompt_answers_are_consumed_after_merge() {
        let state = test_state();
        let session = upsert_browser_flow_auth_session(
            &state,
            Some("auth-session-captcha-consume".to_string()),
            "unicom".to_string(),
            "pan.wo.cn-web".to_string(),
            "unicom_sms_login_submit_code".to_string(),
            BTreeMap::new(),
            BTreeMap::new(),
        );
        let prompt = ensure_auth_capture_prompt_for_interactive_request(
            &state,
            &session,
            &BrowserFlowInteractivePromptRequest {
                input_id: "image_captcha".to_string(),
                field_label: "Image Captcha".to_string(),
                field_kind: AuthPromptFieldKind::Captcha,
                placeholder: Some("Type the captcha".to_string()),
                message: "Enter the captcha and resume the flow.".to_string(),
            },
        );

        let mut store = state
            .auth
            .capture_prompts
            .lock()
            .expect("auth capture prompt store poisoned");
        store
            .get_mut(&prompt.prompt_id)
            .expect("captcha prompt should exist")
            .answer("a1b2".to_string());
        drop(store);

        let mut merged = BTreeMap::new();
        merge_answered_prompts_into_inputs(
            &state,
            "auth-session-captcha-consume",
            &mut merged,
            &BTreeSet::from(["image_captcha".to_string()]),
        );
        assert_eq!(
            merged.get("image_captcha"),
            Some(&serde_json::Value::String("a1b2".to_string()))
        );

        let mut merged_again = BTreeMap::new();
        merge_answered_prompts_into_inputs(
            &state,
            "auth-session-captcha-consume",
            &mut merged_again,
            &BTreeSet::from(["image_captcha".to_string()]),
        );
        assert!(!merged_again.contains_key("image_captcha"));

        let prompts = auth_session_prompts(&state, "auth-session-captcha-consume");
        assert!(prompts.is_empty());
    }

